/*
 * Focused harness for CVE-2024-25062 regression intent:
 * drive xmlTextReaderRead with XInclude expansion and DTD validation.
 * Returns 0 on clean completion, 1 on reader error, 2 on setup failure.
 */
#include <stdio.h>
#include <stdlib.h>
#include <libxml/xmlreader.h>
#include <libxml/xmlversion.h>

int main(int argc, char **argv) {
    xmlTextReaderPtr reader;
    int ret, n = 0;
    int options = XML_PARSE_XINCLUDE | XML_PARSE_DTDVALID | XML_PARSE_DTDLOAD;

    if (argc < 2) {
        fprintf(stderr, "usage: %s XMLFILE [options]\n", argv[0]);
        return 2;
    }
    if (argc > 2)
        options = (int) strtol(argv[2], NULL, 0);

    reader = xmlReaderForFile(argv[1], NULL, options);
    if (reader == NULL) {
        fprintf(stderr, "xmlReaderForFile returned NULL\n");
        return 2;
    }

    while ((ret = xmlTextReaderRead(reader)) == 1) {
        n++;
        if (n > 200000) {
            fprintf(stderr, "node limit reached\n");
            break;
        }
    }

    printf("nodes=%d final_ret=%d\n", n, ret);
    xmlFreeTextReader(reader);
    xmlCleanupParser();
    return (ret < 0) ? 1 : 0;
}

